require "test_helper"
class ZzQueriesTest < ActionDispatch::IntegrationTest
  setup { sign_in_as :kevin; @comment = comments(:logo_agreement_jz) }

  def count_queries(&block)
    count = 0
    cb = ->(*, payload) { count += 1 unless payload[:name].in?(%w[ SCHEMA TRANSACTION ]) || payload[:cached] }
    ActiveSupport::Notifications.subscribed(cb, "sql.active_record", &block)
    count
  end

  test "constant queries" do
    few = count_queries { get card_comment_reactions_path(@comment.card, @comment) }
    few_json = count_queries { get card_comment_reactions_path(@comment.card, @comment), as: :json }
    Current.set(session: sessions(:jz)) { 10.times { |i| @comment.reactions.create!(content: "r#{i}") } }
    many = count_queries { get card_comment_reactions_path(@comment.card, @comment) }
    many_json = count_queries { get card_comment_reactions_path(@comment.card, @comment), as: :json }
    puts "html: #{few} -> #{many}; json: #{few_json} -> #{many_json}"
    assert true
  end
end
EOF
